module three_states (\n    input clk,\n    input rst_n,\n    input start,\n    input [191:0] grid_flat,\n    output [5:0] min_roads,\n    output valid,\n    output done\n);\n\n    // State declarations\n    localparam [2:0] IDLE    = 3'd0;\n    localparam [2:0] LOAD    = 3'd1;\n    localparam [2:0] BFS1    = 3'd2;\n    localparam [2:0] BFS2    = 3'd3;\n    localparam [2:0] BFS3    = 3'd4;\n    localparam [2:0] COMPUTE = 3'd5;\n    localparam [2:0] FINISH  = 3'd6;\n\n    reg [2:0] state;\n    reg [2:0] next_state;\n\n    // Grid storage\n    reg [2:0] grid [0:7][0:7];\n\n    // Distance arrays\n    reg [5:0] dist1 [0:7][0:7];\n    reg [5:0] dist2 [0:7][0:7];\n    reg [5:0] dist3 [0:7][0:7];\n\n    // BFS registers\n    reg [5:0] queue [0:63];\n    reg [5:0] head;\n    reg [5:0] tail;\n    reg [5:0] current_cell;\n    reg [2:0] neighbor_cnt;\n    reg [7:0] bfs_timeout;\n    reg [1:0] bfs_state;\n\n    // Compute registers\n    reg [7:0] min_total;\n    reg [5:0] cell_idx;\n    reg [7:0] total_cost;\n\n    // Output registers\n    reg [5:0] min_roads_reg;\n    reg valid_reg;\n    reg done_reg;\n\n    assign min_roads = min_roads_reg;\n    assign valid = valid_reg;\n    assign done = done_reg;\n\n    integer i,j; // Loop variables\n\n    // Main FSM\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialize all arrays and registers\n            state <= IDLE;\n            done_reg <= 1'b0;\n            valid_reg <= 1'b0;\n            min_roads_reg <= 6'd0;\n            head <= 6'd0;\n            tail <= 6'd0;\n            neighbor_cnt <= 3'd0;\n            cell_idx <= 6'd0;\n            current_cell <= 6'd0;\n            bfs_timeout <= 8'd0;\n            min_total <= 8'd255;\n            \n            for (i = 0; i < 8; i = i + 1) begin\n                for (j = 0; j < 8; j = j + 1) begin\n                    grid[i][j] <= 3'd0;\n                    dist1[i][j] <= 6'd63;\n                    dist2[i][j] <= 6'd63;\n                    dist3[i][j] <= 6'd63;\n                end\n            end\n\n            for (i = 0; i < 64; i = i + 1) begin\n                queue[i] <= 6'd0;\n            end\n        end else begin\n            state <= next_state;\n\n            case (state)\n                IDLE: begin\n                    done_reg <= 1'b0;\n                    if (start) begin\n                        // Reset BFS states before starting\n                        head <= 6'd0;\n                        tail <= 6'd0;\n                        neighbor_cnt <= 3'd0;\n                        bfs_timeout <= 8'd0;\n                        cell_idx <= 6'd0;\n                        min_total <= 8'd255;\n                        valid_reg <= 1'b0;\n                    end\n                end\n\n                LOAD: begin\n                    // Unpack grid_flat into 2D array\n                    for (i = 0; i < 8; i = i + 1) begin\n                        for (j = 0; j < 8; j = j + 1) begin\n                            grid[i][j] <= grid_flat[(i*8+j)*3 +: 3];\n                        end\n                    end\n                end\n\n                BFS1, BFS2, BFS3: begin\n                    if (neighbor_cnt == 3'd0) begin\n                        if (head != tail) begin\n                            current_cell <= queue[head];\n                            head <= head + 6'd1;\n                            neighbor_cnt <= 3'd1;\n                        end\n                    end else begin\n                        if (neighbor_cnt <= 3'd4) begin\n                            // Get neighbor coordinates (simplified)\n                            reg [2:0] r, c;\n                            reg [2:0] new_r, new_c;\n                            r = current_cell[5:3];\n                            c = current_cell[2:0];\n\n                            case(neighbor_cnt)\n                                3'd1: begin new_r = r;     new_c = c + 1; end\n                                3'd2: begin new_r = r;     new_c = c - 1; end\n                                3'd3: begin new_r = r + 1; new_c = c;     end\n                                3'd4: begin new_r = r - 1; new_c = c;     end\n                            endcase\n\n                            if (new_r < 8 && new_c < 8 && new_r >= 0 && new_c >= 0) begin\n                                reg [2:0] n_state;\n                                n_state = grid[new_r][new_c];\n\n                                if (n_state != 3'd0 && n_state != 3'd5) begin\n                                    reg [5:0] new_dist;\n                                    reg [5:0] curr_dist;\n\n                                    // Get current distance\n                                    if (state == BFS1) curr_dist = dist1[r][c];\n                                    else if (state == BFS2) curr_dist = dist2[r][c];\n                                    else curr_dist = dist3[r][c];\n\n                                    // Calculate new distance\n                                    new_dist = (n_state == 3'd4) ? curr_dist + 1 : curr_dist;\n\n                                    // Update distance if improved\n                                    if (state == BFS1 && new_dist < dist1[new_r][new_c]) begin\n                                        dist1[new_r][new_c] <= new_dist;\n                                        queue[tail] <= {new_r, new_c};\n                                        tail <= tail + 1;\n                                    end\n                                    else if (state == BFS2 && new_dist < dist2[new_r][new_c]) begin\n                                        dist2[new_r][new_c] <= new_dist;\n                                        queue[tail] <= {new_r, new_c};\n                                        tail <= tail + 1;\n                                    end\n                                    else if (state == BFS3 && new_dist < dist3[new_r][new_c]) begin\n                                        dist3[new_r][new_c] <= new_dist;\n                                        queue[tail] <= {new_r, new_c};\n                                        tail <= tail + 1;\n                                    end\n                                end\n                            end\n\n                            neighbor_cnt <= neighbor_cnt + 1;\n                        end else begin\n                            neighbor_cnt <= 0;\n                            bfs_timeout <= bfs_timeout + 1;\n                        end\n                    end\n                end\n\n                COMPUTE: begin\n                    if (cell_idx < 64) begin\n                        reg [2:0] r, c;\n                        r = cell_idx / 8;\n                        c = cell_idx % 8;\n                        \n                        if (dist1[r][c] < 63 && dist2[r][c] < 63 && dist3[r][c] < 63) begin\n                            total_cost = dist1[r][c] + dist2[r][c] + dist3[r][c];\n                            if (grid[r][c] == 3'd4) total_cost = total_cost - 2;\n                            if (total_cost < min_total) min_total <= total_cost;\n                        end\n                        cell_idx <= cell_idx + 1;\n                    end\n                end\n\n                FINISH: begin\n                    done_reg <= 1'b1;\n                    if (min_total < 255) begin\n                        valid_reg <= 1'b1;\n                        min_roads_reg <= min_total[5:0];\n                    end else begin\n                        valid_reg <= 1'b0;\n                        min_roads_reg <= 6'd63;\n                    end\n                end\n            endcase\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: begin\n                if (start) next_state = LOAD;\n            end\n            LOAD: next_state = BFS1;\n            BFS1: begin\n                if ((head == tail) || (bfs_timeout > 8'd200)) next_state = BFS2;\n            end\n            BFS2: begin\n                if ((head == tail) || (bfs_timeout > 8'd200)) next_state = BFS3;\n            end\n            BFS3: begin\n                if ((head == tail) || (bfs_timeout > 8'd200)) next_state = COMPUTE;\n            end\n            COMPUTE: begin\n                if (cell_idx == 64) next_state = FINISH;\n            end\n            FINISH: next_state = IDLE;\n            default: next_state = IDLE;\n        endcase\n    end\n\nendmodule